-- 1. messages 表新增撤回时间列（NULL 表示未撤回）
ALTER TABLE public.messages ADD COLUMN IF NOT EXISTS revoked_at TIMESTAMPTZ;

COMMENT ON COLUMN public.messages.revoked_at IS '消息撤回时间；仅发送者可在对方未读且限时内撤回';

-- 2. 收紧 UPDATE 策略：原 users_update_read_at_messages 允许任意会话成员改任意行，
--    会绕过「只能撤回自己的消息」约束。改为仅发送者可更新自己发出的消息
--    （标记已读是写对方的消息，由下方专用策略放行）。
DROP POLICY IF EXISTS users_update_read_at_messages ON public.messages;

CREATE POLICY senders_update_own_messages ON public.messages
 FOR UPDATE USING (sender_id = auth.uid());

CREATE POLICY receivers_mark_read_messages ON public.messages
 FOR UPDATE USING (
   EXISTS (
     SELECT 1 FROM public.conversations c
     WHERE c.id = messages.conversation_id
     AND (c.user1_id = auth.uid() OR c.user2_id = auth.uid())
   )
 );

